const STAGES = [
  '0-new',
  '1-deduped',
  '2-suppression-checked',
  '3-researched',
  '4-scored',
  '5-gated',
  '6-drafted',
  '7-validated',
];

const TERMINAL_STATUSES = new Set([
  'historic',
  'below-threshold',
  'suppressed',
  'validated',
  'quarantined',
]);

const PATHWAYS = [
  ['catalyst_fit', 'Catalyst'],
  ['core_fit', 'Core'],
  ['circle_fit', 'Circle'],
  ['strategic_partner_fit', 'Strategic Partner'],
];

const DNC_PAIRS = [
  ['DIRECT_NUMBER', 'DIRECT_NUMBER_DNC'],
  ['MOBILE_PHONE', 'MOBILE_PHONE_DNC'],
  ['PERSONAL_PHONE', 'PERSONAL_PHONE_DNC'],
  ['SKIPTRACE_WIRELESS_NUMBERS', 'SKIPTRACE_DNC'],
];

const DRAFT_STEPS = ['initial', 'followup_1', 'followup_2', 'followup_3', 'followup_4'];
const DEFAULT_SCORE_POLICY = Object.freeze({ stop_below: 60, priority_above: 80 });

class ControlledStop extends Error {
  constructor(code) {
    super(code);
    this.code = code;
  }
}

class ValidationFailure extends Error {
  constructor(stage, errors) {
    super(`${stage}: ${errors.join('; ')}`);
    this.stage = stage;
    this.errors = errors;
  }
}

function normalizeEmail(value) {
  return String(value ?? '').trim().toLowerCase();
}

function validEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function splitList(value) {
  if (Array.isArray(value)) return value.map(String).map((v) => v.trim()).filter(Boolean);
  if (value === null || value === undefined || String(value).trim() === '') return Array.from([]);
  return String(value).split(',').map((v) => v.trim()).filter(Boolean);
}

function normalizePhone(value) {
  const raw = String(value ?? '').trim();
  const digits = raw.replace(/\D/g, '');
  return digits ? `+${digits}` : '';
}

function stageRank(stage) {
  const rank = STAGES.indexOf(stage);
  return rank < 0 ? 0 : rank;
}

function numberInRange(value) {
  return Number.isFinite(Number(value)) && Number(value) >= 0 && Number(value) <= 100;
}

function validateDraft(step, value) {
  const errors = [];
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return Array.of(`${step} must be an object`);
  }
  if (typeof value.subject !== 'string' || !value.subject.trim()) errors.push(`${step}.subject is required`);
  if (typeof value.body !== 'string' || !value.body.trim()) errors.push(`${step}.body is required`);
  return errors;
}

function validateConfig(config) {
  const errors = [];
  if (!config || typeof config !== 'object') return Array.of('config is required');
  if (!String(config.run_id ?? '').trim()) errors.push('run_id is required');
  if (!Number.isInteger(config.batch_cap) || config.batch_cap < 1 || config.batch_cap > 20) {
    errors.push('batch_cap must be an integer from 1 to 20');
  }
  if (!Number.isInteger(config.ai_call_cap) || config.ai_call_cap < 0) {
    errors.push('ai_call_cap must be a non-negative integer');
  }
  if (!Number.isFinite(config.cost_cap_usd) || config.cost_cap_usd < 0) {
    errors.push('cost_cap_usd must be a non-negative number');
  }
  if (!Number.isInteger(config.max_attempts) || config.max_attempts < 1 || config.max_attempts > 2) {
    errors.push('max_attempts must be 1 or 2');
  }
  if (!['synthetic', 'internal-synthetic-integration'].includes(config.mode)) {
    errors.push('this draft engine permits synthetic modes only');
  }
  const stopBelow = Number(config.score_stop_below ?? DEFAULT_SCORE_POLICY.stop_below);
  const priorityAbove = Number(config.score_priority_above ?? DEFAULT_SCORE_POLICY.priority_above);
  if (!Number.isFinite(stopBelow) || stopBelow < 0 || stopBelow > 100) {
    errors.push('score_stop_below must be from 0 to 100');
  }
  if (!Number.isFinite(priorityAbove) || priorityAbove < 0 || priorityAbove > 100) {
    errors.push('score_priority_above must be from 0 to 100');
  }
  if (Number.isFinite(stopBelow) && Number.isFinite(priorityAbove) && stopBelow > priorityAbove) {
    errors.push('score_stop_below cannot exceed score_priority_above');
  }
  return errors;
}

function scoreBand(overall, config = {}) {
  const score = Number(overall);
  const stopBelow = Number(config.score_stop_below ?? DEFAULT_SCORE_POLICY.stop_below);
  const priorityAbove = Number(config.score_priority_above ?? DEFAULT_SCORE_POLICY.priority_above);
  if (score < stopBelow) return 'below-threshold';
  if (score > priorityAbove) return 'priority';
  return 'normal';
}

function selectEmailRoute(record) {
  const personal = normalizeEmail(record.PERSONAL_VERIFIED_EMAILS);
  const business = normalizeEmail(record.BUSINESS_VERIFIED_EMAILS);
  if (validEmail(business)) return { email_key: business, email_used: 'business', personal, business };
  if (validEmail(personal)) return { email_key: personal, email_used: 'personal-fallback', personal, business };
  return { email_key: '', email_used: '', personal, business };
}

function indexLedger(ledger) {
  const index = new Map();
  const put = (email, row) => {
    const key = normalizeEmail(email);
    if (key && !index.has(key)) index.set(key, row);
  };
  for (const row of ledger) {
    put(row.email_key, row);
    put(row.email_business, row);
    put(row.email_personal, row);
  }
  return index;
}

function evaluateDnc(record) {
  const numbers = new Map();
  const errors = [];
  const rawFlagEvidence = {};
  let anyDncColumn = false;

  for (const [numberField, flagField] of DNC_PAIRS) {
    const rawNumbers = splitList(record[numberField]);
    const flags = splitList(record[flagField]).map((v) => v.toUpperCase());
    rawFlagEvidence[flagField] = {
      numbers: rawNumbers,
      flags,
    };
    if (rawNumbers.length || flags.length) anyDncColumn = true;

    if (rawNumbers.length !== flags.length) {
      errors.push(`${numberField}/${flagField} length mismatch ${rawNumbers.length}/${flags.length}`);
      continue;
    }

    for (let i = 0; i < rawNumbers.length; i += 1) {
      const number = normalizePhone(rawNumbers[i]);
      const flag = flags[i];
      if (!number) errors.push(`${numberField}[${i}] has no digits`);
      if (!['Y', 'N'].includes(flag)) errors.push(`${flagField}[${i}] must be Y or N`);
      if (!number || !['Y', 'N'].includes(flag)) continue;
      if (!numbers.has(number)) numbers.set(number, new Set());
      numbers.get(number).add(flag);
    }
  }

  if (errors.length) {
    return {
      errors,
      any_dnc: true,
      phone_used: '',
      withheld: [],
      normalized_phones: [],
      raw_flags: rawFlagEvidence,
    };
  }

  const callable = [];
  const withheld = [];
  for (const [number, flags] of numbers) {
    if (flags.has('Y')) withheld.push(`${number}:dnc-y`);
    else callable.push(number);
  }

  // No DNC evidence means no phone can be treated as callable. Phase 1 is email-only.
  if (!anyDncColumn) {
    for (const [numberField] of DNC_PAIRS) {
      for (const value of splitList(record[numberField])) {
        const number = normalizePhone(value);
        if (number) withheld.push(`${number}:dnc-unknown`);
      }
    }
  }

  return {
    errors: [],
    any_dnc: withheld.some((value) => value.endsWith(':dnc-y')),
    phone_used: callable[0] ?? '',
    withheld: [...new Set(withheld)],
    normalized_phones: [...numbers.keys()],
    raw_flags: rawFlagEvidence,
  };
}

function stableHash(value) {
  const text = String(value ?? '');
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

function choosePathway(scores) {
  const ranked = PATHWAYS
    .map(([field, label]) => ({ field, label, score: Number(scores[field]) }))
    .sort((a, b) => b.score - a.score);
  return {
    winner: ranked[0],
    tied: ranked.length > 1 && ranked[0].score === ranked[1].score,
    tied_labels: ranked.filter((entry) => entry.score === ranked[0].score).map((entry) => entry.label),
  };
}

function makeRun(config, records) {
  return {
    run_id: config.run_id,
    evidence_class: config.evidence_class ?? 'internal-synthetic-integration',
    workflow_id: config.workflow_id ?? '',
    started: config.now ?? '2026-08-09T00:00:00.000Z',
    ended: '',
    batch_cap: config.batch_cap,
    ai_call_cap: config.ai_call_cap,
    cost_cap_usd: config.cost_cap_usd,
    score_stop_below: Number(config.score_stop_below ?? DEFAULT_SCORE_POLICY.stop_below),
    score_priority_above: Number(config.score_priority_above ?? DEFAULT_SCORE_POLICY.priority_above),
    leads_in: records.length,
    processed: 0,
    skipped_duplicate: 0,
    suppressed: 0,
    below_threshold: 0,
    quarantined: 0,
    errors: 0,
    ai_calls_total: 0,
    est_cost_usd: 0,
    stopped_at_stage: '',
    status: 'running',
  };
}

function newLedgerRow(record, config, route) {
  return {
    email_key: route.email_key,
    email_business: route.business,
    email_personal: route.personal,
    email_used: route.email_used,
    first_name: String(record.FIRST_NAME ?? '').trim(),
    last_name: String(record.LAST_NAME ?? '').trim(),
    source_batch: String(record.source_batch ?? config.source_batch ?? 'synthetic'),
    source_row_hash: String(record.source_row_hash ?? '').trim(),
    status: 'queued',
    stage: '0-new',
    suppress_reason: '',
    pathway: '',
    score_band: '',
    dnc_direct: String(record.DIRECT_NUMBER_DNC ?? ''),
    dnc_mobile: String(record.MOBILE_PHONE_DNC ?? ''),
    dnc_personal: String(record.PERSONAL_PHONE_DNC ?? ''),
    dnc_skiptrace: String(record.SKIPTRACE_DNC ?? ''),
    dnc_raw_flags_json: '',
    dnc_normalized_phones: '',
    phone_used: '',
    phone_withheld: '',
    ai_calls: 0,
    tokens_in: 0,
    tokens_out: 0,
    est_cost_usd: 0,
    attempts: 0,
    last_error: '',
    quarantine_reason: '',
    pushed_ghl: false,
    pushed_instantly: false,
    first_seen: config.now ?? '2026-08-09T00:00:00.000Z',
    last_updated: config.now ?? '2026-08-09T00:00:00.000Z',
    run_id: config.run_id,
    research_digest: '',
    score_payload_json: '',
    draft_payload_json: '',
    output_hash: '',
    prompt_version: config.prompt_version ?? 'legacy-sub1-2026-08-07',
  };
}

function copyRow(row) {
  return JSON.parse(JSON.stringify(row));
}

function invokeMock(stage, attempts, validator, row, run, config) {
  const available = Array.isArray(attempts) ? attempts : [];
  const validationErrors = [];

  for (let attempt = 0; attempt < config.max_attempts; attempt += 1) {
    const response = available[attempt] ?? { error: `missing mock response for ${stage}` };
    const cost = Number(response.cost_usd ?? 0);
    if (run.ai_calls_total + 1 > config.ai_call_cap) throw new ControlledStop('AI_CALL_CAP_REACHED');
    if (run.est_cost_usd + cost > config.cost_cap_usd + 1e-12) throw new ControlledStop('COST_CAP_REACHED');

    run.ai_calls_total += 1;
    run.est_cost_usd = Number((run.est_cost_usd + cost).toFixed(8));
    row.ai_calls += 1;
    row.tokens_in += Number(response.tokens_in ?? 0);
    row.tokens_out += Number(response.tokens_out ?? 0);
    row.est_cost_usd = Number((row.est_cost_usd + cost).toFixed(8));
    row.attempts += 1;

    const errors = response.error ? [String(response.error)] : validator(response.value);
    if (!errors.length) return response.value;
    validationErrors.push(`attempt ${attempt + 1}: ${errors.join(', ')}`);
  }

  throw new ValidationFailure(stage, validationErrors);
}

function stageCheckpoint(row, stage, config, inputIndex) {
  row.stage = stage;
  row.last_updated = config.now ?? '2026-08-09T00:00:00.000Z';
  if (config.kill_after?.input_index === inputIndex && config.kill_after?.stage === stage) {
    throw new ControlledStop('SYNTHETIC_KILL');
  }
}

function eventFor(index, row, overrides = {}) {
  return {
    input_index: index,
    run_id: row.run_id,
    email_key: row.email_key,
    final_status: row.status,
    final_stage: row.stage,
    suppress_reason: row.suppress_reason,
    pathway: row.pathway,
    ai_calls: row.ai_calls,
    est_cost_usd: row.est_cost_usd,
    exception: row.last_error || row.quarantine_reason || '',
    output_hash: row.output_hash || '',
    ...overrides,
  };
}

/**
 * Pure synthetic state-machine harness for the Phase 1 controlled core.
 * It performs no I/O. The caller owns reading and single-writer persistence.
 */
function runControlledCore({ config, records, ledger = [], mocks = {} }) {
  const configErrors = validateConfig(config);
  if (configErrors.length) throw new Error(`Invalid config: ${configErrors.join('; ')}`);
  if (!Array.isArray(records)) throw new Error('records must be an array');
  if (!Array.isArray(ledger)) throw new Error('ledger must be an array');

  const workingLedger = ledger.map(copyRow);
  let ledgerIndex = indexLedger(workingLedger);
  const run = makeRun(config, records);
  const events = [];
  let currentRow = null;

  const persist = (row) => {
    const exact = workingLedger.findIndex((candidate) => normalizeEmail(candidate.email_key) === row.email_key);
    if (exact >= 0) workingLedger[exact] = copyRow(row);
    else workingLedger.push(copyRow(row));
    ledgerIndex = indexLedger(workingLedger);
  };

  for (let index = 0; index < records.length; index += 1) {
    if (run.processed >= config.batch_cap) {
      run.status = 'cap-reached';
      run.stopped_at_stage = 'BATCH_CAP_REACHED';
      break;
    }

    const record = records[index];
    const route = selectEmailRoute(record);
    const emailBusiness = route.business;
    const emailPersonal = route.personal;
    const businessMatch = emailBusiness ? ledgerIndex.get(emailBusiness) : null;
    const personalMatch = emailPersonal ? ledgerIndex.get(emailPersonal) : null;
    const aliasMatches = [businessMatch, personalMatch].filter(Boolean);
    // A terminal suppression on either identity alias must outrank a resumable checkpoint.
    // Otherwise a current business-email row could bypass a historic/bounced personal alias.
    const terminalMatch = aliasMatches.find((candidate) => TERMINAL_STATUSES.has(candidate.status));
    const prior = terminalMatch ?? businessMatch ?? personalMatch ?? null;
    const sameWork = prior &&
      String(prior.source_row_hash ?? '') === String(record.source_row_hash ?? '') &&
      !TERMINAL_STATUSES.has(prior.status);

    currentRow = sameWork ? copyRow(prior) : newLedgerRow(record, config, route);
    currentRow.run_id = config.run_id;
    currentRow.email_business = emailBusiness;
    currentRow.email_personal = emailPersonal;
    currentRow.email_used = route.email_used;

    try {
      if (!route.email_key) {
        currentRow.status = 'quarantined';
        currentRow.quarantine_reason = 'EMAIL_ROUTE_REQUIRED';
        currentRow.email_key = `quarantine:${config.run_id}:${index}`;
        persist(currentRow);
        run.quarantined += 1;
        run.processed += 1;
        events.push(eventFor(index, currentRow));
        continue;
      }

      if (prior && !sameWork) {
        currentRow.status = 'suppressed';
        currentRow.stage = '2-suppression-checked';
        currentRow.suppress_reason = prior.suppress_reason === 'bounced' ? 'bounced' :
          prior.status === 'historic' ? 'already-contacted' : 'duplicate';
        currentRow.last_error = `identity matched prior ledger row ${prior.email_key}`;
        // Preserve the prior person row; the duplicate attempt is visible in proof events.
        run.skipped_duplicate += 1;
        run.suppressed += 1;
        run.processed += 1;
        events.push(eventFor(index, currentRow, { matched_ledger_key: prior.email_key }));
        continue;
      }

      if (stageRank(currentRow.stage) < stageRank('1-deduped')) {
        stageCheckpoint(currentRow, '1-deduped', config, index);
        persist(currentRow);
      }

      if (stageRank(currentRow.stage) < stageRank('2-suppression-checked')) {
        const dnc = evaluateDnc(record);
        currentRow.phone_used = dnc.phone_used;
        currentRow.phone_withheld = dnc.withheld.join(', ');
        currentRow.dnc_raw_flags_json = JSON.stringify(dnc.raw_flags);
        currentRow.dnc_normalized_phones = dnc.normalized_phones.join(', ');
        if (dnc.errors.length) {
          currentRow.status = 'quarantined';
          currentRow.quarantine_reason = `DNC_INPUT_INVALID: ${dnc.errors.join('; ')}`;
          stageCheckpoint(currentRow, '2-suppression-checked', config, index);
          persist(currentRow);
          run.quarantined += 1;
          run.processed += 1;
          events.push(eventFor(index, currentRow));
          continue;
        }
        if (dnc.any_dnc) {
          currentRow.status = 'suppressed';
          currentRow.suppress_reason = 'dnc';
          stageCheckpoint(currentRow, '2-suppression-checked', config, index);
          persist(currentRow);
          run.suppressed += 1;
          run.processed += 1;
          events.push(eventFor(index, currentRow));
          continue;
        }
        stageCheckpoint(currentRow, '2-suppression-checked', config, index);
        persist(currentRow);
      }

      const leadMock = mocks[route.email_key] ?? mocks[emailBusiness] ?? mocks[emailPersonal] ?? {};

      if (stageRank(currentRow.stage) < stageRank('3-researched')) {
        const research = invokeMock(
          'research', leadMock.research,
          (value) => typeof value === 'string' && value.trim() ? [] : ['research must be non-empty text'],
          currentRow, run, config,
        );
        currentRow.research_digest = research;
        stageCheckpoint(currentRow, '3-researched', config, index);
        persist(currentRow);
      }

      if (stageRank(currentRow.stage) < stageRank('4-scored')) {
        const overall = invokeMock(
          'overall-score', leadMock.overall,
          (value) => numberInRange(value?.Overall_SAMPLE_Fit) ? [] : ['Overall_SAMPLE_Fit must be 0-100'],
          currentRow, run, config,
        );
        currentRow.over_all_SAMPLE_fit = Number(overall.Overall_SAMPLE_Fit);
        currentRow.score_band = scoreBand(currentRow.over_all_SAMPLE_fit, config);
        const scorePayload = {
          ...overall,
          score_band: currentRow.score_band,
          score_policy: {
            stop_below: Number(config.score_stop_below ?? DEFAULT_SCORE_POLICY.stop_below),
            priority_above: Number(config.score_priority_above ?? DEFAULT_SCORE_POLICY.priority_above),
          },
        };

        if (currentRow.score_band !== 'below-threshold') {
          for (const [field] of PATHWAYS) {
            const category = invokeMock(
              field, leadMock[field],
              (value) => numberInRange(value?.[field]) ? [] : [`${field} must be 0-100`],
              currentRow, run, config,
            );
            currentRow[field] = Number(category[field]);
            Object.assign(scorePayload, category);
          }
        }

        currentRow.score_payload_json = JSON.stringify(scorePayload);
        currentRow.status = 'scored';
        stageCheckpoint(currentRow, '4-scored', config, index);
        persist(currentRow);
      }

      if (stageRank(currentRow.stage) < stageRank('5-gated')) {
        if (scoreBand(currentRow.over_all_SAMPLE_fit, config) === 'below-threshold') {
          currentRow.status = 'below-threshold';
          currentRow.suppress_reason = 'below-threshold';
          stageCheckpoint(currentRow, '5-gated', config, index);
          persist(currentRow);
          run.below_threshold += 1;
          run.processed += 1;
          events.push(eventFor(index, currentRow));
          continue;
        }
        const pathway = choosePathway(currentRow);
        if (pathway.tied) {
          currentRow.status = 'quarantined';
          currentRow.quarantine_reason = `PATHWAY_TIE: ${pathway.tied_labels.join(', ')}`;
          stageCheckpoint(currentRow, '5-gated', config, index);
          persist(currentRow);
          run.quarantined += 1;
          run.processed += 1;
          events.push(eventFor(index, currentRow));
          continue;
        }
        currentRow.pathway = pathway.winner.label;
        currentRow.status = 'scored';
        stageCheckpoint(currentRow, '5-gated', config, index);
        persist(currentRow);
      }

      if (stageRank(currentRow.stage) < stageRank('6-drafted')) {
        const drafts = {
          honorific: invokeMock(
            'honorific', leadMock.honorific,
            (value) => typeof value === 'string' && value.trim() ? Array.from([]) :
              Array.of('honorific must be non-empty text'),
            currentRow, run, config,
          ),
        };
        for (const step of DRAFT_STEPS) {
          drafts[step] = invokeMock(
            `draft-${step}`, leadMock[`draft_${step}`],
            (value) => validateDraft(step, value),
            currentRow, run, config,
          );
        }
        currentRow.draft_payload_json = JSON.stringify(drafts);
        currentRow.status = 'drafted';
        stageCheckpoint(currentRow, '6-drafted', config, index);
        persist(currentRow);
      }

      if (stageRank(currentRow.stage) < stageRank('7-validated')) {
        let draftPayload;
        try {
          draftPayload = JSON.parse(currentRow.draft_payload_json);
        } catch {
          throw new ValidationFailure('final-output', ['draft_payload_json is not valid JSON']);
        }
        const errors = DRAFT_STEPS.flatMap((step) => validateDraft(step, draftPayload[step]));
        if (errors.length) throw new ValidationFailure('final-output', errors);
        currentRow.output_hash = `synthetic:${stableHash(JSON.stringify({
          email_key: currentRow.email_key,
          email_used: currentRow.email_used,
          pathway: currentRow.pathway,
          scores: currentRow.score_payload_json,
          drafts: currentRow.draft_payload_json,
          prompt_version: currentRow.prompt_version,
        }))}`;
        currentRow.status = 'validated';
        stageCheckpoint(currentRow, '7-validated', config, index);
        persist(currentRow);
      }

      run.processed += 1;
      events.push(eventFor(index, currentRow));
    } catch (error) {
      if (error instanceof ControlledStop) {
        persist(currentRow);
        run.status = error.code === 'SYNTHETIC_KILL' ? 'stopped' : 'cap-reached';
        run.stopped_at_stage = `${currentRow.stage}:${error.code}`;
        events.push(eventFor(index, currentRow, { interrupted: true, exception: error.code }));
        break;
      }
      if (error instanceof ValidationFailure) {
        currentRow.status = 'quarantined';
        currentRow.quarantine_reason = error.message;
        persist(currentRow);
        run.quarantined += 1;
        run.processed += 1;
        events.push(eventFor(index, currentRow));
        continue;
      }
      currentRow.status = 'error';
      currentRow.last_error = String(error?.message ?? error);
      persist(currentRow);
      run.errors += 1;
      run.processed += 1;
      events.push(eventFor(index, currentRow));
    }
  }

  if (run.status === 'running') run.status = 'completed';
  run.ended = config.now ?? '2026-08-09T00:00:00.000Z';
  return { run, ledger: workingLedger, events };
}


